steps.script:
var p = tree.current_scene.game_log_panel
var target = null
for card in p._card_container.get_children():
	var txt := ""
	for n in card.find_children("*", "Label", true, false):
		txt += " " + n.text
	for n in card.find_children("*", "RichTextLabel", true, false):
		txt += " " + n.get_parsed_text()
	if "Dreadherder" in txt:
		target = card
if target == null:
	return false
p._scroll.ensure_control_visible(target)
return true
